package com.ljuniversity.companion.ui;

import com.ljuniversity.companion.model.PlannerTask;
import com.ljuniversity.companion.util.PlannerStore;
import javax.swing.*;
import javax.swing.border.*;
import javax.swing.event.*;
import java.awt.*;
import java.awt.event.*;
import java.io.IOException;
import java.nio.file.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.List;

/** Real desktop UI. Offline by default, with explicitly fictional campus ideas. */
public final class DesktopWorkspace extends JFrame {
    private static final Color INK=new Color(31,42,67), BLUE=new Color(44,67,132), BG=new Color(246,247,251), MUTED=new Color(109,118,137), LINE=new Color(226,230,239), ORANGE=new Color(228,169,91);
    private static final Font BODY=new Font("SansSerif",Font.PLAIN,14);
    private final PlannerStore store;
    private final JPanel content=new JPanel(new BorderLayout()), nav=new JPanel();
    private final JLabel status=label("Offline workspace. No account, campus server or AI connection.",12,MUTED);
    private final Map<String,JButton> navButtons=new LinkedHashMap<>();
    private String page="Overview", search="", filter="All tasks";
    private JPanel taskRows;
    private JLabel taskCount;

    public DesktopWorkspace(PlannerStore store) {
        super("Campus Connect · Personal workspace");this.store=store;
        setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);setSize(1360,900);setMinimumSize(new Dimension(1100,760));setLocationRelativeTo(null);
        getContentPane().setBackground(BG);setLayout(new BorderLayout());
        UIManager.put("OptionPane.messageFont",BODY);UIManager.put("OptionPane.buttonFont",BODY);UIManager.put("TextField.font",BODY);UIManager.put("TextArea.font",BODY);
        add(sidebar(),BorderLayout.WEST);content.setOpaque(false);add(content,BorderLayout.CENTER);
        status.setBorder(new EmptyBorder(10,28,10,20));add(status,BorderLayout.SOUTH);
        showPage("Overview");if(store.warning()!=null)status.setText(store.warning());
    }
    private static JLabel label(String text,int size,Color color){JLabel l=new JLabel(text);l.setAlignmentX(Component.LEFT_ALIGNMENT);l.putClientProperty("html.disable",Boolean.TRUE);l.setFont(new Font("SansSerif",Font.PLAIN,size));l.setForeground(color);return l;}
    private static JLabel title(String text,int size){JLabel l=label(text,size,INK);l.setFont(l.getFont().deriveFont(Font.BOLD));return l;}
    private static JPanel panel(LayoutManager layout){JPanel p=new JPanel(layout);p.setAlignmentX(Component.LEFT_ALIGNMENT);p.setOpaque(false);return p;}
    private static JPanel stack(){JPanel p=panel(null);p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));return p;}
    private static JPanel row(Component... components){JPanel p=panel(new FlowLayout(FlowLayout.LEFT,12,0));for(Component c:components)p.add(c);return p;}
    private static JPanel card(){JPanel p=new RoundedPanel(Color.WHITE,18);p.setLayout(new BorderLayout(16,16));p.setBorder(new EmptyBorder(24,24,24,24));return p;}
    private static JTextArea paragraph(String text){JTextArea a=new JTextArea(text);a.setAlignmentX(Component.LEFT_ALIGNMENT);a.setFont(BODY);a.setForeground(MUTED);a.setLineWrap(true);a.setWrapStyleWord(true);a.setEditable(false);a.setOpaque(false);a.setFocusable(false);return a;}
    private static JButton button(String text,boolean primary,Runnable action){JButton b=new JButton(text);b.setAlignmentX(Component.LEFT_ALIGNMENT);b.setFont(new Font("SansSerif",Font.BOLD,12));b.setBackground(primary?BLUE:Color.WHITE);b.setForeground(primary?Color.WHITE:BLUE);b.setFocusPainted(true);b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));b.setBorder(BorderFactory.createCompoundBorder(new LineBorder(primary?BLUE:LINE,1,true),new EmptyBorder(11,16,11,16)));b.addActionListener(e->action.run());return b;}
    private JPanel sidebar(){JPanel side=new JPanel(new BorderLayout());side.setBackground(INK);side.setPreferredSize(new Dimension(226,0));side.setBorder(new EmptyBorder(35,24,25,20));JPanel top=stack();JLabel mark=label("C / C",30,Color.WHITE);mark.setFont(mark.getFont().deriveFont(Font.BOLD));top.add(mark);top.add(Box.createVerticalStrut(12));top.add(label("CAMPUS CONNECT",12,new Color(210,220,245)));top.add(Box.createVerticalStrut(10));top.add(label("Your day. Your space.",11,new Color(152,167,199)));side.add(top,BorderLayout.NORTH);
        nav.setOpaque(false);nav.setLayout(new BoxLayout(nav,BoxLayout.Y_AXIS));nav.setBorder(new EmptyBorder(45,0,0,0));
        String[] names={"Overview","My planner","Explore campus","Career notes","About this project"};String[] icons={"01","02","03","04","05"};for(int i=0;i<names.length;i++){String name=names[i];JButton b=button(icons[i]+"    "+name,false,()->showPage(name));b.setHorizontalAlignment(SwingConstants.LEFT);b.setMaximumSize(new Dimension(190,45));b.setBorder(new EmptyBorder(13,10,13,6));b.setBackground(INK);b.setForeground(new Color(183,196,222));b.setAlignmentX(LEFT_ALIGNMENT);nav.add(b);nav.add(Box.createVerticalStrut(12));navButtons.put(name,b);}side.add(nav,BorderLayout.CENTER);
        JPanel bottom=stack();bottom.add(label("DESKTOP EDITION",9,new Color(166,183,211)));bottom.add(Box.createVerticalStrut(10));bottom.add(label("●  Offline-first",12,new Color(194,216,187)));bottom.add(Box.createVerticalStrut(8));bottom.add(label("Personal, not a campus portal",10,new Color(149,164,191)));side.add(bottom,BorderLayout.SOUTH);return side;
    }
    private void showPage(String name){page=name;navButtons.forEach((key,b)->{b.setBackground(key.equals(name)?new Color(57,74,112):INK);b.setForeground(key.equals(name)?Color.WHITE:new Color(183,196,222));});content.removeAll();JPanel body=stack();body.setBorder(new EmptyBorder(28,34,30,34));JPanel top=panel(new BorderLayout());top.add(label("WORKSPACE  /  "+name.toUpperCase(Locale.ROOT),10,MUTED),BorderLayout.WEST);top.add(label(LocalDate.now().format(DateTimeFormatter.ofPattern("EEE, dd MMM yyyy")),11,MUTED),BorderLayout.EAST);top.setMaximumSize(new Dimension(Integer.MAX_VALUE,25));body.add(top);body.add(Box.createVerticalStrut(27));
        switch(name){case "My planner"->planner(body);case "Explore campus"->explore(body);case "Career notes"->career(body);case "About this project"->about(body);default->overview(body);}
        body.add(Box.createVerticalGlue());JScrollPane scroll=new JScrollPane(body);scroll.setBorder(null);scroll.getViewport().setBackground(BG);scroll.getVerticalScrollBar().setUnitIncrement(20);scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);content.add(scroll);content.revalidate();content.repaint();}
    private void heading(JPanel body,String name,String subtitle){body.add(title(name,34));body.add(Box.createVerticalStrut(10));JTextArea sub=paragraph(subtitle);sub.setMaximumSize(new Dimension(Integer.MAX_VALUE,52));sub.setPreferredSize(new Dimension(700,44));body.add(sub);body.add(Box.createVerticalStrut(23));}
    private void full(JPanel body,JComponent component,int height){component.setAlignmentX(LEFT_ALIGNMENT);component.setMaximumSize(new Dimension(Integer.MAX_VALUE,height));component.setPreferredSize(new Dimension(800,height));body.add(component);body.add(Box.createVerticalStrut(22));}
    private void overview(JPanel body){heading(body,"A little focus. A better day.","Your personal corner of campus life. Plan what matters, find your next idea and make room for the good stuff.");JPanel hero=new RoundedPanel(new Color(230,235,249),20);hero.setLayout(new BorderLayout(24,10));hero.setBorder(new EmptyBorder(28,28,28,28));JPanel copy=stack();copy.add(label("MAKE TODAY YOURS",10,BLUE));copy.add(Box.createVerticalStrut(12));copy.add(title("Big plans start with one small task.",25));copy.add(Box.createVerticalStrut(14));copy.add(paragraph("Keep your own tasks in one place. No sign-in, no database setup and no information sent to a university server."));copy.add(Box.createVerticalStrut(18));copy.add(row(button("+  Add your first task",true,()->taskDialog(null)),button("Open my planner  →",false,()->showPage("My planner"))));hero.add(copy,BorderLayout.CENTER);JLabel art=label("✳",100,BLUE);art.setPreferredSize(new Dimension(130,130));art.setHorizontalAlignment(SwingConstants.CENTER);hero.add(art,BorderLayout.EAST);full(body,hero,230);
        long open=store.all().stream().filter(t->!t.done()).count(),done=store.all().stream().filter(PlannerTask::done).count(),overdue=store.all().stream().filter(t->t.overdue(LocalDate.now())).count();JPanel stats=panel(new GridLayout(1,3,16,0));stats.add(stat("OPEN TASKS",open,"One thing at a time",BLUE));stats.add(stat("COMPLETED",done,"Progress, at your pace",new Color(48,123,96)));stats.add(stat("PAST DUE",overdue,"A chance to re-plan",new Color(177,111,45)));full(body,stats,128);
        JPanel lower=panel(new GridLayout(1,2,20,0));JPanel upcoming=card();upcoming.add(title("Next on your list",18),BorderLayout.NORTH);JPanel list=stack();List<PlannerTask> next=store.list("","Open").stream().limit(3).toList();if(next.isEmpty()){list.add(label("A fresh page, ready for your plans.",13,MUTED));list.add(Box.createVerticalStrut(16));list.add(button("Create a personal task  →",false,()->taskDialog(null)));}else for(PlannerTask t:next){list.add(label(shorten(t.title(),37),13,INK));list.add(label(t.due().toString()+"  ·  "+t.category(),11,MUTED));list.add(Box.createVerticalStrut(14));}upcoming.add(list);lower.add(upcoming);
        JPanel discover=card();discover.setBackground(new Color(250,241,224));discover.add(title("A life beyond the timetable.",18),BorderLayout.NORTH);discover.add(paragraph("Explore sample club ideas and plan your own next step. These are fictional suggestions, not scheduled university events."));discover.add(button("Find a little inspiration  →",false,()->showPage("Explore campus")),BorderLayout.SOUTH);lower.add(discover);full(body,lower,225);
    }
    private JPanel stat(String label,long number,String note,Color accent){JPanel c=card();c.setBorder(new EmptyBorder(18,22,18,22));c.add(DesktopWorkspace.label(label,9,MUTED),BorderLayout.NORTH);c.add(DesktopWorkspace.label(String.format("%02d",number),33,accent));c.add(DesktopWorkspace.label(note,11,MUTED),BorderLayout.SOUTH);return c;}
    private void planner(JPanel body){heading(body,"Less in your head. More on your list.","Personal tasks, saved on this computer. Search, set a date, tick things off. No campus data or official deadlines are loaded.");JPanel toolbar=panel(new BorderLayout(16,0));JTextField find=new JTextField(search);find.setFont(BODY);find.setBorder(BorderFactory.createCompoundBorder(new LineBorder(LINE),new EmptyBorder(12,13,12,13)));find.setToolTipText("Search task titles and notes");find.getAccessibleContext().setAccessibleName("Search tasks");JComboBox<String> select=new JComboBox<>(new String[]{"All tasks","Open","Completed"});select.setSelectedItem(filter);select.getAccessibleContext().setAccessibleName("Filter task status");JPanel actions=row(select,button("+ New task",true,()->taskDialog(null)));toolbar.add(find);toolbar.add(actions,BorderLayout.EAST);full(body,toolbar,44);taskCount=label("",11,MUTED);body.add(taskCount);body.add(Box.createVerticalStrut(15));taskRows=stack();taskRows.setAlignmentX(LEFT_ALIGNMENT);body.add(taskRows);find.getDocument().addDocumentListener(new DocumentListener(){public void insertUpdate(DocumentEvent e){update();}public void removeUpdate(DocumentEvent e){update();}public void changedUpdate(DocumentEvent e){update();}private void update(){search=find.getText();renderTasks();}});select.addActionListener(e->{filter=(String)select.getSelectedItem();renderTasks();});renderTasks();JPanel foot=row(button("Export planner JSON",false,this::export),button("Clear completed…",false,()->{long count=store.all().stream().filter(PlannerTask::done).count();if(count==0){message("No completed tasks to clear.");return;}if(confirm("Remove "+count+" completed tasks from this device?"))mutate(()->store.clearCompleted(),"Completed tasks cleared.");}));full(body,foot,52);}
    private void renderTasks(){taskRows.removeAll();List<PlannerTask> tasks=store.list(search,filter);taskCount.setText(tasks.size()+" tasks shown · "+store.all().size()+" total on this device");if(tasks.isEmpty()){JPanel empty=card();empty.add(title(store.all().isEmpty()?"Your planner starts here.":"No matching tasks.",22),BorderLayout.NORTH);empty.add(paragraph(store.all().isEmpty()?"Add a task that matters to you. Your plans stay on this computer.":"Try a different search or status filter."));empty.add(button("+ Add a task",true,()->taskDialog(null)),BorderLayout.SOUTH);full(taskRows,empty,180);}for(PlannerTask task:tasks){JPanel item=card();item.setBorder(new EmptyBorder(18,20,18,20));JCheckBox check=new JCheckBox();check.setOpaque(false);check.setSelected(task.done());check.setToolTipText(task.done()?"Mark incomplete":"Mark complete");check.getAccessibleContext().setAccessibleName("Complete task: "+task.title());check.addActionListener(e->mutate(()->store.put(task.completed(check.isSelected())),"Task updated."));item.add(check,BorderLayout.WEST);JPanel text=stack();text.add(title(shorten(task.title(),45),16));text.add(Box.createVerticalStrut(8));text.add(label(task.category()+"    ·    "+task.due()+ (task.overdue(LocalDate.now())?"    ·    Past due":"")+(task.done()?"    ·    Completed":""),11,task.overdue(LocalDate.now())?new Color(166,88,38):MUTED));item.add(text);item.add(row(button("Edit",false,()->taskDialog(task)),button("Remove",false,()->{if(confirm("Remove this personal task?"))mutate(()->store.remove(task.id()),"Task removed.");})),BorderLayout.EAST);full(taskRows,item,90);}taskRows.revalidate();taskRows.repaint();}
    private void taskDialog(PlannerTask previous){JTextField name=new JTextField(previous==null?"":previous.title(),28);JTextField due=new JTextField(previous==null?LocalDate.now().plusDays(1).toString():previous.due().toString());JTextArea notes=new JTextArea(previous==null?"":previous.notes(),4,28);notes.setLineWrap(true);notes.setWrapStyleWord(true);JComboBox<String> category=new JComboBox<>(new String[]{"Academic","Personal","Campus"});if(previous!=null)category.setSelectedItem(previous.category());JPanel form=stack();for(Component c:new Component[]{label("Title (up to 120 characters)",12,INK),name,label("Due date · YYYY-MM-DD",12,INK),due,label("Category",12,INK),category,label("Notes (optional, up to 2000 characters)",12,INK),new JScrollPane(notes)}){if(c instanceof JComponent jc)jc.setAlignmentX(LEFT_ALIGNMENT);form.add(c);form.add(Box.createVerticalStrut(9));}name.getAccessibleContext().setAccessibleName("Task title");due.getAccessibleContext().setAccessibleName("Due date YYYY-MM-DD");notes.getAccessibleContext().setAccessibleName("Task notes");while(true){int result=JOptionPane.showConfirmDialog(this,form,previous==null?"New personal task":"Edit personal task",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE);if(result!=JOptionPane.OK_OPTION)return;try{PlannerTask task=previous==null?PlannerTask.create(name.getText(),notes.getText(),due.getText().strip(),(String)category.getSelectedItem()):new PlannerTask(previous.id(),name.getText(),notes.getText(),LocalDate.parse(due.getText().strip()),(String)category.getSelectedItem(),previous.done());store.put(task);showPage(page);message("Task saved on this device.");return;}catch(java.time.format.DateTimeParseException e){error("Use a real calendar date in YYYY-MM-DD format.");}catch(IllegalArgumentException|IOException e){error(e instanceof IOException?"The task could not be saved. Another window may have changed it, the file may be full, or folder access may be unavailable. Your existing file was preserved.":e.getMessage());}}}
    private void explore(JPanel body){heading(body,"Find your people. Try something new.","Fictional campus ideas for your own planning, not official clubs, bookings or scheduled events.");String[][] ideas={{"BUILD TOGETHER","A tiny project, a new perspective.","Gather a small group and make something useful in an afternoon.","Plan a peer coding session"},{"MAKE SOME SPACE","Creativity looks good on everyone.","Set aside time for a sketchbook, a photograph or a creative experiment.","Plan a creative break"},{"MOVE A LITTLE","Take the long way outside.","A short walk or an easy game can make room for a clearer head.","Plan an outdoor break"}};JPanel grid=panel(new GridLayout(1,3,18,0));for(String[] idea:ideas){JPanel c=card();JPanel copy=stack();copy.add(label(idea[0],9,BLUE));copy.add(Box.createVerticalStrut(22));JTextArea h=paragraph(idea[1]);h.setFont(new Font("SansSerif",Font.BOLD,22));h.setForeground(INK);copy.add(h);copy.add(Box.createVerticalStrut(15));copy.add(paragraph(idea[2]));c.add(copy);c.add(button("Add as a personal task",false,()->{try{store.put(PlannerTask.create(idea[3],"Personal idea, not an official event or booking.",LocalDate.now().plusDays(7).toString(),"Campus"));message("Idea added to your personal planner, not booked or registered.");showPage("My planner");}catch(Exception e){error("Could not save the idea. Check your local data folder.");}}),BorderLayout.SOUTH);grid.add(c);}full(body,grid,330);JPanel note=card();note.add(title("A note on the original project",18),BorderLayout.NORTH);note.add(paragraph("The legacy source includes campus events, scores and faculty-feedback modules backed by a separately configured MySQL schema. They are not connected here. No real university partners, event dates or student records are represented by this offline workspace."));full(body,note,140);}
    private void career(JPanel body){heading(body,"A direction, not a prediction.","A simple career reflection space. No invented growth percentages, live labour-market claims or AI recommendations.");String[][] tracks={{"Build products","Explore software engineering","Make a small app, write tests and explain one trade-off in its README."},{"Ask better questions","Explore data work","Choose a public dataset, check its license and describe one question before analysing it."},{"Make systems safer","Explore security","Study a small application you own, map its inputs and practise defensive testing locally."}};for(String[] track:tracks){JPanel c=card();JPanel copy=stack();copy.add(label(track[0].toUpperCase(Locale.ROOT),9,BLUE));copy.add(Box.createVerticalStrut(8));copy.add(title(track[1],21));copy.add(Box.createVerticalStrut(10));copy.add(paragraph(track[2]));c.add(copy);c.add(button("Make a personal next step",false,()->{try{store.put(PlannerTask.create(track[1],track[2],LocalDate.now().plusDays(7).toString(),"Personal"));showPage("My planner");message("A reflection prompt was added, not a personalised career assessment.");}catch(Exception e){error("Could not save this step.");}}),BorderLayout.EAST);full(body,c,145);}body.add(label("The optional legacy Gemini client is not called by this offline workspace.",11,MUTED));}
    private void about(JPanel body){heading(body,"Built for campus. Kept personal.","A student-built Java Swing project, refreshed as an offline-first desktop workspace. Not an official university service.");JPanel c=card();c.add(title("What this edition does",22),BorderLayout.NORTH);c.add(paragraph("Your personal planner works without MySQL, an API key or an account. It saves titles, notes, due dates and completion state to your user folder. Sample campus ideas and career reflections are clearly labelled. Nothing is sent over the network by this workspace.\n\nOriginal MySQL-backed modules remain in source behind an explicit opt-in legacy launch mode. They are not an integrated production system; see the README for schema, account and privacy limits. A direct desktop database credential is not a safe multi-user authentication architecture."));full(body,c,220);JPanel data=card();data.add(title("Your plans stay here",22),BorderLayout.NORTH);data.add(paragraph("Data file: "+store.path()+"\n\nThis file is not encrypted. Other people using your computer account can read it. Avoid sensitive student or faculty information. Export a JSON backup before clearing data or moving computers. If saved data cannot be read, this app leaves the file untouched and switches to session-only work."));data.add(button("Export planner JSON",false,this::export),BorderLayout.SOUTH);full(body,data,250);if(store.warning()!=null)body.add(paragraph(store.warning()));}
    private void export(){JFileChooser chooser=new JFileChooser();chooser.setDialogTitle("Export personal planner JSON");chooser.setSelectedFile(new java.io.File("campus-connect-planner.json"));if(chooser.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;Path target=chooser.getSelectedFile().toPath();if(Files.exists(target)&&!confirm("Replace the existing export file?"))return;try{store.export(target);message("Planner exported to your chosen file.");}catch(IOException e){error("Export failed. Choose a writable path different from the active data file.");}}
    @FunctionalInterface private interface Change{void run()throws IOException;}
    private void mutate(Change change,String message){try{change.run();showPage(page);message(message);}catch(IOException e){error("Save failed. Restart if another window changed the file, or check file size and folder access. The existing file and task list were preserved.");}}
    private boolean confirm(String message){return JOptionPane.showConfirmDialog(this,message,"Confirm local change",JOptionPane.YES_NO_OPTION,JOptionPane.QUESTION_MESSAGE)==JOptionPane.YES_OPTION;}
    private void error(String message){JOptionPane.showMessageDialog(this,message,"Campus Connect",JOptionPane.WARNING_MESSAGE);}
    private void message(String text){status.setText(store.warning()==null?text:text+" Session only: saved file was left untouched.");}
    private static String shorten(String value,int max){return value.length()>max?value.substring(0,max-1)+"…":value;}
    private static final class RoundedPanel extends JPanel {
        private final int radius;
        RoundedPanel(Color background,int radius){this.radius=radius;setBackground(background);setOpaque(false);}
        @Override protected void paintComponent(Graphics graphics){Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(getBackground());g.fillRoundRect(0,0,getWidth(),getHeight(),radius,radius);g.dispose();super.paintComponent(graphics);}
    }
}
